-- Independent MealDeck post-install extension, generated by Supabase CLI 3.0.0.
-- Apply this COMPLETE file atomically after the reviewed independent profile.
-- The base installer, its manifest and its compatibility hash remain unchanged.
-- Staff prices only: no public catalogue, availability, checkout or KDS changes.

begin;
set local lock_timeout='5s';
set local statement_timeout='30s';
set local check_function_bodies=on;

do $profile$
begin
  if pg_catalog.to_regclass('mealdeck_private.installation') is null
    or pg_catalog.to_regnamespace('dishbee_private') is not null then
    raise exception 'mealdeck_modifier_prices_independent_profile_required';
  end if;
  if current_user in ('anon','authenticated','service_role') or not exists(
    select 1 from pg_catalog.pg_class c
    where c.oid='mealdeck_private.installation'::pg_catalog.regclass
      and pg_catalog.pg_has_role(current_user,c.relowner,'USAGE')
  ) then
    raise exception 'mealdeck_modifier_prices_database_owner_required';
  end if;
  if not exists(select 1 from mealdeck_private.installation i
      where i.singleton and i.profile='mealdeck-independent-v1')
    or pg_catalog.to_regprocedure('mealdeck_ops_private.can(uuid,uuid,text)') is null
    or pg_catalog.to_regclass('public.mealdeck_ops_audit_log') is null then
    raise exception 'mealdeck_modifier_prices_installed_profile_required';
  end if;
end $profile$;

-- Deliberately scoped staff API. Base tables have no API-role grants. These
-- security-definer entry points use the existing verified-user permission
-- helper, a fixed empty search_path and explicit per-function execution ACLs.
create or replace function public.mealdeck_ops_modifier_prices(p_tenant uuid)
returns table(
  option_id uuid,group_id uuid,group_name text,option_name text,
  price_delta_pence integer,active boolean,affected_item_count integer
)
language plpgsql stable security definer set search_path=''
as $$
begin
  if auth.uid() is null or not mealdeck_ops_private.can(p_tenant,null,'menu.read') then
    raise exception 'mealdeck_ops_forbidden' using errcode='42501';
  end if;
  return query
    select o.id,g.id,g.name::text,o.name::text,o.price_delta_pence,o.active,
      (select count(*)::integer from public.menu_item_modifier_groups link
        join public.menu_items item on item.tenant_id=link.tenant_id and item.id=link.item_id
        where link.tenant_id=p_tenant and link.group_id=g.id)
    from public.modifier_options o
    join public.modifier_groups g on g.tenant_id=o.tenant_id and g.id=o.group_id
    where o.tenant_id=p_tenant
    order by g.name,o.name,o.id;
end;
$$;
revoke all on function public.mealdeck_ops_modifier_prices(uuid)
  from public,anon,authenticated,service_role;
grant execute on function public.mealdeck_ops_modifier_prices(uuid) to authenticated;

create or replace function public.mealdeck_ops_modifier_update_price(
  p_tenant uuid,p_option uuid,p_price_pence integer,p_expected_price_pence integer
) returns jsonb
language plpgsql security definer set search_path=''
as $$
declare
  v_before public.modifier_options%rowtype;
  v_group_name text;
  v_affected integer;
  v_changed boolean;
begin
  if auth.uid() is null or not mealdeck_ops_private.can(p_tenant,null,'menu.write') then
    raise exception 'mealdeck_ops_forbidden' using errcode='42501';
  end if;
  if p_price_pence is null or p_price_pence<0 or p_price_pence>1000000
    or p_expected_price_pence is null or p_expected_price_pence<0
    or p_expected_price_pence>1000000 then
    raise exception 'mealdeck_ops_modifier_invalid_price';
  end if;
  select * into v_before from public.modifier_options o
    where o.tenant_id=p_tenant and o.id=p_option for update;
  if not found then raise exception 'mealdeck_ops_modifier_not_found'; end if;
  -- A request may have waited behind another editor. Recheck both authority
  -- and the expected integer-pence value after acquiring the option row lock.
  if auth.uid() is null or not mealdeck_ops_private.can(p_tenant,null,'menu.write') then
    raise exception 'mealdeck_ops_forbidden' using errcode='42501';
  end if;
  if v_before.price_delta_pence is distinct from p_expected_price_pence then
    raise exception 'mealdeck_ops_modifier_price_conflict';
  end if;
  select g.name into v_group_name from public.modifier_groups g
    where g.tenant_id=p_tenant and g.id=v_before.group_id;
  if not found then raise exception 'mealdeck_ops_modifier_not_found'; end if;
  select count(*)::integer into v_affected from public.menu_item_modifier_groups link
    join public.menu_items item on item.tenant_id=link.tenant_id and item.id=link.item_id
    where link.tenant_id=p_tenant and link.group_id=v_before.group_id;
  v_changed:=v_before.price_delta_pence<>p_price_pence;
  if v_changed then
    update public.modifier_options set price_delta_pence=p_price_pence
      where tenant_id=p_tenant and id=p_option;
    insert into public.mealdeck_ops_audit_log(
      tenant_id,location_id,actor_id,action,entity_type,entity_id,previous_value,next_value
    ) values(p_tenant,null,auth.uid(),'menu.modifier_price.update','modifier_option',p_option,
      jsonb_build_object('pricePence',v_before.price_delta_pence,'groupId',v_before.group_id,
        'optionName',v_before.name,'active',v_before.active),
      jsonb_build_object('pricePence',p_price_pence,'groupId',v_before.group_id,
        'optionName',v_before.name,'active',v_before.active,'affectedItemCount',v_affected));
  end if;
  return jsonb_build_object('option_id',p_option,'group_id',v_before.group_id,
    'group_name',v_group_name,'option_name',v_before.name,'price_delta_pence',p_price_pence,
    'active',v_before.active,'affected_item_count',v_affected,'changed',v_changed);
end;
$$;
revoke all on function public.mealdeck_ops_modifier_update_price(uuid,uuid,integer,integer)
  from public,anon,authenticated,service_role;
grant execute on function public.mealdeck_ops_modifier_update_price(uuid,uuid,integer,integer)
  to authenticated;

commit;
